<?php
session_start(); require_once 'GEX-EC-05-SCRUM-Sprint-3-Desarrollo-ConfiguracionDeConexion-20261007-V1.0.php';
if (!isset($_SESSION['usuario_id'])) { header('Location: GEX-EC-05-SCRUM-Sprint-3-Desarrollo-InicioDeSesion-20261007-V1.0.php'); exit(); }
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['notificacion_id'])) { $stmt = $pdo->prepare('UPDATE notificaciones SET leida = 1 WHERE id = ? AND usuario_id = ?'); $stmt->execute([(int) $_POST['notificacion_id'], $_SESSION['usuario_id']]); }
$stmt = $pdo->prepare('SELECT id, mensaje, leida, fecha_creacion FROM notificaciones WHERE usuario_id = ? ORDER BY fecha_creacion DESC'); $stmt->execute([$_SESSION['usuario_id']]); $notificaciones = $stmt->fetchAll(PDO::FETCH_ASSOC);
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Notificaciones - Soporte</title><link rel="stylesheet" href="GEX-EC-05-SCRUM-Sprint-3-Desarrollo-EstilosDeInterfaz-20261007-V1.0.css"></head><body><div class="dashboard-layout"><?php include 'GEX-EC-05-SCRUM-Sprint-3-Desarrollo-MenuDeNavegacion-20261007-V1.0.php'; ?><div class="main-wrapper"><header class="topbar"><div class="topbar-title"><h2>Notificaciones</h2></div><div class="topbar-user"><span><strong><?php echo htmlspecialchars($_SESSION['usuario_nombre']); ?></strong></span><span class="user-badge"><?php echo htmlspecialchars($_SESSION['usuario_rol']); ?></span><a href="GEX-EC-05-SCRUM-Sprint-3-Desarrollo-CierreDeSesion-20261007-V1.0.php" class="btn-logout">Cerrar Sesión</a></div></header><main class="content-area"><div class="ui-card"><h1>Actividad reciente</h1><?php if (!$notificaciones): ?><div class="empty-state"><p>No tienes notificaciones.</p></div><?php else: ?><?php foreach ($notificaciones as $n): ?><div class="notification-item <?php echo $n['leida'] ? '' : 'unread'; ?>"><div><strong><?php echo htmlspecialchars($n['mensaje']); ?></strong><small><?php echo htmlspecialchars(date('d/m/Y H:i', strtotime($n['fecha_creacion']))); ?></small></div><?php if (!$n['leida']): ?><form method="POST"><input type="hidden" name="notificacion_id" value="<?php echo (int) $n['id']; ?>"><button class="badge-btn" type="submit">Marcar leída</button></form><?php endif; ?></div><?php endforeach; ?><?php endif; ?></div></main></div></div></body></html>
